 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc, grid[rr][cc]))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] != bg:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append(comp)
    motif = max(comps, key=len)
    rmin, rmax = min(x[0] for x in motif), max(x[0] for x in motif)
    cmin, cmax = min(x[1] for x in motif), max(x[1] for x in motif)
    ar, ac = (rmin + rmax) // 2, (cmin + cmax) // 2
    points = {(r, c) for r, c, _ in motif}
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg and (r, c) not in points]
    out = [row[:] for row in grid]
    # Copy the motif's complete rectangular stamp, including background holes,
    # centered on each isolated marker.
    for mr, mc in markers:
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                nr, nc = mr + r - ar, mc + c - ac
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = grid[r][c]
    return out
